INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (100, 'I.03094', ' Berikan pujian terhadap perilaku ibu yang benar Edukasi  Ajarkan teknik menyusui yang tepat sesuai kebutuhan ibu Konseling Nutrisi', 'Memberikan bimbingan dalam melakukan modifikasi asupan nutrisi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (101, 'I.10336', 'Kaloborasi  Rujuk pada ahli gizi/jika perlu Konseling Prakonsepsi', 'Memberikan bimbingan terhadap pasangan usia subur sebelum kehamilan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (102, 'I.07214', 'Konseling Seksualitas', 'Memberikan bimbingan seksual pada pasangan sehingga mmpu menjlankan fungsinya secara optimal.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (103, 'I.12461', ' Kolaborasi dengan spesialis seksologi/jika perlu Konsultasi', 'Memberikan pertimbangan untuk memecahkan masalah keperawatan dan/atau kesehatan yang dialami pasien,keluarga,kelompok,atau komunitas.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (104, 'I.12462', ' Jelskan keuntungan dan kerugian masing-masung solusi  Anjurkan meningkatkan kemandirian menyeselesaikan masalah Konsultasi Via Telepon', 'Memberikan pertimbangan untuk memecahkan masalah keperawatan dan/atau kesehatan yang dialami pasien,kelurga,kelompok,atau komunitas melalui m,edia telepon');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (105, 'I.09282', ' Anjurkan meningkatkan kemandirian menyelesaikan masalah Kontrak Perilaku Positif', 'Melakukan Negoisasi kesepakatan untuk memperkuat perbhan perilaku tertentu.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (106, 'I.12482', ' Anjurkan menuliskan tujuan sendiri/jika perlu Koordinasi Diskusi Keluarga', 'Menyeimbangkan kegiatan keluarga untuk menvcapai tujuan bersama anggota keluarga.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (107, 'I.14504', 'Koordinasi praoperasi', 'Mengkoordinasikan persiapan pasien sebelum menjalani operasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (108, 'I.03099', 'Manajemen Demam', 'Mengidentifikasi dan mengelola peningkatan suhu tubuh akibat pirogen endogen');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (109, 'I.09286', 'Manajemen Demensia', 'Mengidentifikasi dan mengelola pasien yang mengalami konfusi kronis.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (110, 'I.09287', 'Manajemen Depresi Pascapersalinan', 'Mengidentifikasi dan mengelola gangguan adaptasi psikologi postpartum yang terjadi beberapa minggu sampai beberapa bulan setelah melahirkan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (111, 'I.03100', 'Manajemen Dialisis Peritoneal', 'Mengidentifikasi dan mengelola proses pengeluaran sisa metabolisme, mempertahankan balans cairan dan elektrolit melalui pembuluh darah diperitonium.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (112, 'I.03101', 'Manajemen Diare', 'Mengidentifikasi dan mengelola diare dan dampaknya.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (113, 'I.06190', 'Manajemen Disrefleksia', 'Mengidentifikasi dan mengelola refleks dan respon otonom yang tidak tepat pada lesi sevikal atau toraks.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (114, 'I.14505', 'Manajemen Efek Samping Obat', 'Mengidentifikasi dan mengelola efek yang tidak di harapkan dari pemberian agen farmakologis.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (115, 'I.06191', 'Manajemen Elektroensefalografi', 'Mengidentifikasi dan mengelola penggunaan diagnostik elektroensefalografi (EEG)');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (116, 'I.06192', 'Manajemen Elektrokonvulsif', 'Mengidentifikasi dan mengelola penatalaksanaan terapi elektrokonvulsif (ECT) yang aman dan efisien.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (117, 'I.03102', 'Menejemen Elektrolit', 'Mengidentiikasi dan mengelola ketidakseimbangan kadar elektrolit serum.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (118, 'I.03103', 'Menejemen Elektrolit: Hiperkalemia', 'Mengidentiikasi dan mengelola kelebihan kadar kalium serum >5,5 mEq/L.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (119, 'I.03104', 'Manajemen Elektrolit: Hiperkalsemia', 'Mengidentifikasi dan mengelola peningkatan kadr kalsium serum >10.5 mFq/L.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (120, 'I.03105', 'Manajmen Elektrolit: Hipermagnesemia', 'Mengidentifikasi dan mengelola peningkatan kadar magnesium serum >2.5 mEq/L.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (121, 'I.03106', 'Manajemen Elektrolit: Hhipernatremia', 'Mengidentifikasi dan mengelola kelebihan kadar natrium serum >145 mEq/L.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (122, 'I.14521', 'Manajemen Kesehatan Kerja', 'Mengidentifikasi dan menegelola lingkungan kerja untuk meningkatkan kesehatan pekerja.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (123, 'I.14513', 'Manajemen Keselamatan Lingkungan', 'Mengidentifikasi dan mengelola lingkungan fisik untuk meningktakan keselamatan');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (124, 'I.14514', 'Manajermen Lingkungan', 'Memfasilisati dan mengelola lingkungan untuk mendaptakan manfaat teraputik, dan kesejahteraan pisikologis.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (125, 'I.14515', 'Manajemen Lingkungna Komunikasi', 'Mengidentifikasi dan mengelola lingkungan fisik, sosaial, budaya, eknomi, dan politik yang mempengaruhi kesehatan masyarakat.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (126, 'I.14516', 'Manajerman Llingkungan: Persiapan Pulang', 'Mengidentifikasi dan mengelola rumah sebagi tempat merawat pasien pasca perawatan di rumah sakit dengan aman dan efektif');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (127, 'I.14517', 'Manajemen Medikasi', 'Mengidentifikasi dan mengeleloa penggunaan agen farmakologis sesuai dengan program pengobatan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (128, 'I.09289', 'Manajemen Mood', 'Mengidentifikasi dan mengelola keselamatan, stabilisasi, pemulihan, dan perawtan gangguan mood (keadaan emosional yang bersifat sementara).');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (129, 'I.03117', 'Manajermen Mual', 'Mengidentifikasi dan mengelola perasaan tidak enak pada bagian tenggorok atau lambung yang dapat menyebabkan muntah.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (130, 'I.03118', 'Manajemen Muntah', 'Mengifentifikasi, mencegah dan mengelola refleks pengeluaran isi lambung Tindakan Observasi - identifikasi karakteristik muntah (mis. warna, konsistensi, adanya darah, waktu, frekuensi dan durasi) - priksa volume muntah Standar - indentifikasi riwayat diet (mis. makanan yang disuka, tudak disukai dan Intervensi Keperawatan Inodenisa budaya) - identifikasi faktor penyebab muntah (mis. pengobatan dan prosedur) - identifikasi kerusakan esofagus dan faring poslerior jika muntah terlalu lama - monitor efek manjemen muntah secara menyeluruh - monotor keseimbangan cairan dan elektrolit Terapeutik - kontrol faktor lingkungan penyebab muntah (mis, bau tak sedap, suara, dan stimulasi visual yang tidak menyenangkan) - kurangi atau hilangkan keadaan penyebab muntah (mis, kecemasan, keakutan) - atur posisi untuk mencegah aspirasi - pertahnkan kepatenan jalan napas - bersihkan mulut dan hidung - berikan dukungan fisik saat muntah (mis. membantu membungkuk atau menundukkan kepala) - berikan kenyamanan selama muntah (mis. kompres dingin di dahi, atau sediakan pakaian kering dan bersih) - berikan cairan yang tidak mengandung karbonasi minimal 30 menit setelah muntah Edukasi - anjurkan membawa kantong plastik untul menamoung muntah - anjurkan memprbanyak istirahat - anjurkan penggunaan teknik nonfarmakologis untuk mengelola muntah (mis. biofeedback, hipnosis, relaksasi, terapi musik, akupresur) Kolaborasi - kolaborasi pemberian antiemerik, jika perlu Manajermen Nefrostomi I.04156 Definisi Mengidentifikasi dan mengelola pengeluaran urine melalui akses selang dari nefron ginjal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (131, 'I.03119', 'Manajemen Nutrisi', 'Menidentifikasi dan mengelola asupan nutrisi yang seimbang');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (132, 'I.15506', 'Manajemen Hipertermia', 'Mengidentifikasi dan mengelola peningkatan suhu tubuh akibat disfungsi termoregulasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (133, 'I.03144', 'Manajemen Hipervolemia', 'Mengidentifikasi dan megelola kelebihan volume cairan intravakuler dan ekstraseluler serta mencegah terjadinya komplikasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (134, 'I.03115', 'Manajemen Hipoglikemia', 'Mengidentifikasi dan mengelola kadar glukosa darah rendah');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (135, 'I.14507', 'Manajemen Hipotermia', 'Mengidentifikasi dan mengelola suhu tubuh dibawah rentang normal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (136, 'I.03116', 'Manajemen Hipovolemia', 'Mengidentifikasi dan mengelola penurunan volume cairan intravaskuler');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (137, 'I.14058', 'Manajemen Imunisasi/Vaksinasi', 'Mengidentifikasi dan mengelola pemberian pemberian kekebalan tubuh secara katif dan pasif');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (138, 'I.04154', 'Nasional yang menyediakan vaksin gratis Manajemen Inkontinensia Urine', 'Mengidentifikasi dan mengelola pasien dengan inkontinensia urine');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (139, 'I.14509', 'Manajemen Isolasi', 'Mengidentifikasi dan mengelola pasien yang berisiko menularkan penyakit, mencederai atau merugikan orang lain');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (140, 'I.14510', 'Manajemen Kasus', 'Mengkoordinasikan perawatan pasien tertentu untuk menurunkan blaya, menurunkan penggunakan sumber daya dan meningkatkan kualitas pelayanan kesehatan serta mencapai hasil yang diharapkan');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (141, 'I.07216', 'Manajemen Kehamilan Tidak Dikehendaki', 'Mengidentifikasi dan mengelola pengambilan keputusan terhadap kehamilan yang tidak direncanakan');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (142, 'I.06193', 'Manajemen Kejang', 'Mengidentifikasi dan mengelola kontraksi otot dan gerakan yang tidak terkendali');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (143, 'I.14511', 'Manajemen Kemoterapi', 'Mengidentifikasi dan mengelola pemberian agen antineoplastik');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (144, 'I.08238', 'Manajemen Nyeri', 'Mengidentifikasi dan mengelola pengalaman sensorik atau emosional yang berkaitan dengan kerusakan jaringan atau fungsional dengan omzet mendadak atau lambat dan berintensitas ringan hingga berat dan konstan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (145, 'I.14518', 'Manajemen Overdosis', 'Mengidentifikasi dan mengelola pasien yang menunjukkan efek toksik akibat mengonsumsi satu atau lebih obat.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (146, 'I.14518', 'Manajemen Pengendalian Marah', 'Mengidentifikasi dan mengelola ekspresi marah dengan cara adaptif dan tanpa kekerasan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (147, 'I.07217', 'Manajemen Penggantian Hormon', 'Mengidentifikasi dan mengelola pemberian hormon tambahan');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (148, 'I.02061', '(mis.karpet,furniture) Pemasangan Stocking Elastis', 'Memasang stocking lentur yang memiliki efek penekanan pada vena tungkai bawah untuk meningkatkan air balik vena ke jantung');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (149, 'I.08243', '(mis.nyeri,ksemutan) Pemberian Analgesik', 'Menyiapkan dan memberikan agen famakologis untuk mengurangi atau menghilangkan rasa sakit.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (150, 'I.08244', 'Pemberian Anastesi', 'Menyiapkan dan memberikan obat anestesi serta memantau respon pasien selama pembeian');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (151, 'I.04158', 'Pemberian Enema', 'Memberikan larutan ke saluran gastrointestinal bagian bawah.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (152, 'I.13485', 'Pemberian Kesaksian', 'Memberikan keterangan untuk kepentingan penyidikan, penuntunan dan peradilan terkait pelayanan keperawatan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (153, 'I.03124', 'Pemberian Kesempatan Menghisap pada Bayi', 'memberikan kesempatan pada bayi untuk kontak kulit ibu dan bayi sehingga bayi mampu menyusu pada payudara ibu.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (154, 'I.03125', 'Pemberian Makanan', 'Memberikan asupan nutrisi melalui oral pada pasien yang tidak mampu makan seacara mandiri.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (155, 'I.03126', 'Pemberian Makanan Enternal', 'Menyiapkan dan memberikan nutrisi melalui selang gastrointestinal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (156, 'I.03127', 'Pemberian Makanan Parental', 'Memberikan nutrisi melalui pembuluh darah vena baik sentral (untuk nutrisi parental total) atau vena perifer (untuk nutrisi parental persial) pada pasien ayng tidak dapat memenuhi kebutuhan nutrisinya melalui oral atau enternal.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (157, 'I.02062', 'Pemberian Obat', 'Mempersiapkan, memberi, dan mengevaluasi keefektifan agen farmakologis yang diprogramkan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (158, 'I.01015', 'Pemberian Obat Inhalasi', 'Menyiapkan dan memberikan agen farmakologis berupa spray (semprotan) aerosol, uap atau bubuk halus untuk mendapatkan efek lokal atau sistemik.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (159, 'I.01016', 'Pemberian Obat Interpleura', 'Menyiapkan dan memberikan agen farmakologi melalui kateter agar berdifusi pada rongga pleura');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (160, 'I.14531', 'Pemberian Obat Intradermal', 'Menyiapkan dan memberikan agen farmakologis melalui jalur intradermal.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (161, 'I.02063', 'Pemberian Obat Intramuskuler', 'Menyiapkan dan memberikan agen farmaklogi melalui jalur intramuscular');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (162, 'I.02064', 'Pemberian Obat Intraseous', 'Menyiapkan dan memberikan agen farmaklogi dengan jarum melalui jalur korteks tulang.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (163, 'I.06199', 'Pemberian Obat Intraspinal', 'Menyiapkan dan memberikan agen farmaklogi melalui jalur epidural atau intratekal.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (164, 'I.01017', 'Pemberian Obat Nasal', 'Menyiapkan dan memberikan agen farmakologis, berupa tetesan melalui hidung untuk mendapatkan efek lokal sistemik.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (165, 'I.03128', 'Pemberian Obat Oral', 'Menyiapkan dan memberikan agen farmakologis melalui mulut untuk mendapatkan efek lokal atau sistemik.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (166, 'I.04159', 'Pemberian Obat Rektal', 'Mempersiapkan dan memberikan agen farmakologis suposturia melalui rektal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (167, 'I.14533', 'Pemberian Obat topikal', 'Menyiapkan dan memberikan agen farmakologis ke permukaan kulit.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (168, 'I.07222', 'Pemberian Obat Vaginal', 'Menyiapkan dan memberikan agen farmakologis via vagina');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (169, 'I.06200', 'Pemberian Obat Ventrikuler', 'Menyiapkan dan memberikan agen farmakologis ke dalam ventrikel lateral otak');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (170, 'I.05180', 'Pembidaian', 'Menstabilisasi, mengimobilisasi, dan memproteksi bagian tubuh yang cedera dengan menggunakan penopang.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (171, 'I.14534', 'Pemeriksaan Kelengkapan Set Emergensi', 'Pemeriksaan dan pemeliharaan kelengkapan alat dan bahan emergensi secara sistematis.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (172, 'I.07224', 'Pemeriksaan Payudara', 'Melakukan inspeksi dan palpasi pada payudara serta area yang terkait untuk mengidentifikasi kesehatan payudara');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (173, 'I.14535', 'Pencegahan Alergi', 'Mengidentifikasi dan menurunkan risiko pasien mengalami risiko alergi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (174, 'I.01018', 'Pencegahan Aspirasi', 'Mengidentifikasi dan mengurangi risiko masuknya partikel makanan/cairan ke dalam paru-paru. Tindakan Observasi - Monitor dengan kesadaran, batuk, muntah dan kemampuan menelan - Monitor status pernapasan - Monitor bunyi napas, terutama setelah makan/minum - Periksa residu gaster sebelum memberi asupan oral - Periksa kepatenan selang nasogastrik sebelum memberi asupan oral Terapeutik - Posisikan semi fowler (30-45 derajat) 30 menit sebelum memberi asupan oral - Pertahankan posisi semi fowler (30-45 derajat) pada pasien tidak sadar - Pertahankan kepatenan jalan napas (mis,teknik head tilt chin lift, jaw thrust,in line) - Pertahankan pengembangan balon endotracheal tube (ETT) - Lakukan perhisapan jalan napas , jika produksi sekret meningkat - Sediakan suction di ruangan - Hindari memberi makan melalui selang gastrointensial, jika residu banyak - Berikan makanan dengan ukuran kecil atau lunak - Berikan obat oral dalam bentuk cair Edukasi - Anjurkan makan secara perlahan - Anjurkan strategi mencegah aspirasi - Anjurkan teknis mengunyah atau menelan, jika perlu Pencegahan Bunuh Diri L.14538 Definisi Mengidentifikasi dan menurunkan risiko merugikan diri sendiri dengan maksud mengakhiri hidup.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (175, 'I.02066', 'Pencegahan Emboli', 'Mengidentifikasi dan menurunkan risiko hambatan aliran darah akibat embolus (mis, pascaoperasi, darah, udara)');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (176, 'I.14539', 'Pencegahan Infeksi', 'Mengidentifikasi dan menurunkan risiko terserang organisme patogenik');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (177, 'I.14541', 'Pencegahan Jatuh', 'Mengidentifikasi dan menurunkan risiko terjatuh akibat perubahan kondisi fisik atau psikologis.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (178, 'I.14541', 'Pencegahan Kebakaran', 'Mengidentifikasi dan menurunkan risiko terjadinya kebakaran');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (179, 'I.04160', 'Pencegahan Konstipasi', 'Mengidentifikasi dan menurunkan risiko terjadinya penurunan frekuensi normal defekasi yang disertai kesulitan pengeluaran feses yang tidak lengkap');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (180, 'I.14543', 'Pencegahan Luka Tekan', 'Mengidentifikasi dan menurunkan risiko kematian jaringan pada area penonjolan tulang akibat penekanan atau gesekan terus menerus');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (181, 'I.09298', 'Pencegahan Penyalahgunaan Zat', 'Mengidentifikasi dan menurunkan risko gaya hidup penggunaan alkohol atau narkoba.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (182, 'I.14544', 'Pencegahan Perilaku Kekerasan', 'Meminimalkan kemarahan yang diekspresikan secara berlebihan dan tidak terkendali secara verbal sampai dengan mencederai orang lain dan/atau merusak lingkungan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (183, 'I.09299', 'Pencegahan Waham', 'Mengidentifikasi dan menurunkan risiko atau komplikasi keyakinan terhadap kesimpulan yang keliru tentang realitas eksternal.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (184, 'I.14546', 'Pendampingan Pembedahan', 'Memfasilitasi dan mengelola paket alat bedah selama tindakan pembedahan berlangsung.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (185, 'I.03130', 'Pendampingan Proses Menyusui', 'Memfasilitasi ibu dalam kegiatan menyusui agar dapat dipertahankan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (186, 'I.
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (187, 'I.02069', 'Pengambilan Sampel Darah Arteri', 'Mengambil darah arteri untuk mendapatkan nilai tekanan parsial oksigen, karbondioksida dan asam basa darah.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (188, 'I.14553', 'Pengontrolan Kesehatan Via Telepon', 'Mengendalikan dan mengevaluasi status kesehatan pasien secara terus menerus dan periodik, melalu teknologe komurukasi telepon.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (189, 'I.09303', 'Pengontrolan Penyalahgunaan Zat I.', 'Mengendahkan penggunaan zat yang tidak sesuai dengan indikasi medis sehwngga dapat mermmbulkan kecanduan hingga kematan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (190, 'I.14556', 'Penjahitan Luka” l.', 'Menyatukan ujung luka dengan menggunakan jarum dan benang jahit steni.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (191, 'I.04161', 'Penurunan Flatus', 'Pencegahan pembentukan fiatus dan fasiktasi pengeluaran gas yang berlebihan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (192, 'I.01021', 'Penyapihan Ventilasi Mekanik', 'Memiasiltasi pasien bemapas tanpa bantuan ventilasi mekar.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (193, 'I.13487', 'Perantaraan Budaya', 'Menghargas perbedaan dan kesamaan budaya pasen dalam membernkan asuhan sepanjang rentang sehat dan sakit sesuai dengan rila-ndai budaya pasien.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (194, 'I.02072', ' Informasikan tentang sistem pelayanan kesehatan Perawatan Alat Topangan Jantung Mekanik', 'Mengidentrfikasi dan merawat pasien yang terpasang perangkat mekanis untuk menunjang fungsi jantung dan sirkulasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (195, 'I.14557', 'Perawatan Amputasi', 'Meningkatkan penyembuhan fisik dan psikologis sebelum dan sesudah amputasi bagian tubuh.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (196, 'I.14558', 'Perawatan Area Insisi', 'Mengidentifikasi dan meningkatkan penyembuhan luka yang ditutup dengan Jahitan. kip. atau staples.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (197, 'I.10338', ' Ajarkan mem'nimaikan tekanan pada tempat insisi  Ajarkan cara merawat area insisi Perawatan bayi', 'Mengindentifikasi dan merawat kesehatan bayi');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (198, 'I.03131', 'PERAWATAN DIALISIS', 'Mengindentifikasi dan merawat pasien yang akan memilih terapi dialisis sebagai pilihan penanganan gagal ginjal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (199, 'I.02074', 'PERAWATAN EMBOLI PARU', 'Mengindentifikasi dan mengelola pasien yang mengalami oklusi sirklusi pulmonal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (200, 'I.02074', 'PERAWATAN EMBOLI PERIFER', 'Mengindentifikasi dan mengelola pasien yang mengalami oklusi perifer');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (201, 'I.05181', 'PERAWATAN GIPS', 'Mengindentifikasi dan merawat pasien yang menjalani imobilisasi ekstermitas dengan gips');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (202, 'I.04162', 'PERAWTAN INKONTINENSIA FEKAL', 'Mengidentifikasi dan merawat pasien yang mengalami pengeluaran fases secara involunter (tidak disadari)');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (203, 'I.04163', 'KOLOBORASI -Kolaborasi pemberian obat diare (mis. Loperamide,atropin) PERAWATAN INKONTINENSIA URINE', 'Mengindentifikasi dan merawat pasien yang mengalami pengeluaran urine secara involuter (tidak disadari)');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (204, 'I.11353', 'PERAWATAN INTEGRITAS KULIT', 'Mengindentifikasi dan merawat kulit untuk menjaga keutuhan, kelembaban dan mencegah perkembangan mikroorganisme');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (205, 'I.02075', 'PERAWATAN JANTUNG', '- Mengindentifikasi,merawat dan membatasi komplikasi akibat ketidak seimbangan anatara suplai dan konsumsi miokard');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (206, 'I.02076', 'PERAWATAN JANTUNG AKUT', 'Mengidentifikasi dan mengelola pasien yang baru mengalami episode ketidakseimbangan anatara ketersediaan dan kebutuhan oksigen miokard');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (207, 'I.14559', 'Perawatan Kanguru', 'Meiakukan tindakan merawat bayi melalui kontak kulit ke kulit antara orang tua dan bayi prematur yang sudah stabil.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (208, 'I.02078', 'Perawatan Kateter Sentral Perifer', 'Mengidentifikasi dan merawat kateter yang diinsersikan secara perifer untuk mengakses sirkulasi sentral.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (209, 'I.04164', 'Perawatan Kateter Urine', 'Mengidentifikasi dan merawat pasien yang menjalani kateterisasi u rine.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (210, 'I.14560', 'Perawatan Kehamilan Risiko Tinggi', 'Mengidentifikasi dan merawat ibu yang berisiko selama masa kehamilan sesuai standar pelayanan yang telah ditetapkan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (211, 'I.14561', 'Perawatan Kehamilan Trimester Kedua dan Ketiga', 'Mengidentifikasi dan merawat ibu hamil pada minggu ke-14 sampai dengan kehamilan cukup bulan (38-40 minggu).');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (212, 'I.15562', 'Perawatan Kehamilan Trimester Pertama', 'Mengidentifikasi dan merawat ibu hamil pada minggu pertama sampai dengan minggu ke-13 kehamilan. Tindakan Observasi - Identifikasi faktor risiko kehamilan (mis. persalinan prematur, preeklampsia, DM) - Identifikasi riwayat merokok, imunisasi masa kehamilan, penggunaan kontrasepsi - Identifikasi riwayat keluarga terhadap kelainan kongenital - Monitor tanda-tanda vital - Timbang berat badan - Ukur tinggi fundus - Periksa gerakan janin - Periksa denyut jantung janin Terapeutik -Lakukan skrining depresi pada kehamilan -Lakukan perawatan gigi dan mulut secara teratur -Motivasi makan porsi kecil tetapi sering -Atur waktu istirahat di antara waktu aktivitas -Batasi masukan cairan sebelum tidur Edukasi -Anjurkan tidak membiarkan perut kosong atau terlalu penuh -Anjurkan mengkonsumsi karbohidrat kering dengan minuman hangat saat bangun tidur - Ajurkan menghindari makanan yang banyak mengandung lemak, gas, bumbu yang merangsang mual -Anjurkan menghentikan kebiasaan merokok -Anjurkan menghindari aktivitas yang berlebihan -Anjurkan melakukan pemeriksaan kehamilan secara teratur -Anjurkan melakukan pemeriksaan laboratorium (mis. Hb, glukosa, albumin, keton) Kolaborasi - Kolaborasi pemeriksaan USG untuk menentukan usia kehamilan Perawatan Kenyamanan 1.08245 Definisi Mengidentifikasi dan merawat pasien untuk meningkatkan rasa nyaman.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (213, 'I.11355', 'Perawatan Kuku', 'Mengidentifikasi dan merawat kuku agar bersih dan sehat serta tidak mengalami lesi kulit akibat perawatan kuku yang tidak tepat.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (214, 'I.14563', 'Perawatan Kulit Praoperasi', 'Mengidentifikasi dan merawat kulit sekitar area operasi sebelum pelaksanaan operasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (215, 'I.06202', 'Perawatan Lensa Kontak', 'Mengidentifikasi dan merawat pasien yang menggunakan lensa kontak serta mencegah terjadinya masalah akibat pengunakan lensa kontak');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (216, 'I.14564', 'Perawatan Luka', 'Mengidentifikasi dan meningkatkan penyembuhan luka serta mencegah terjadinya komplikasi luka. Tindakan Observasi -Monitor karakteristik luka (mis. drainase, warna, ukuran, bau) -Monitor tanda-tanda infeksi Terapeutik -Lepaskan balutan dan plester secara perlahan -Cukur rambut di sekitar daerah luka, jika perlu -Bersihkan dengan cairan NaCl atau pembersih nontoksik, sesuai kebutuhan -Bersihkan jaringan nekrotik Berikan salep yang sesuai ke kulit/lesi, jika perlu - Pasang balutan sesuai jenis luka Pertahankan teknik steril saat melakukan perawatan luka -Ganti balutan sesuai jumlah eksudat dan drainase -Jadwalkan perubahan posisi setiap 2 jam atau sesuai kondisi pasien -Berikan diet dengan kalori 30-35 kkal/kgBB/hari dan protein 1,25-1,5 g/kgBB/hari - Berikan suplemen vitamin dan mineral (mis. vitamin A, vitamin C, Zinc, asam amino), sesuai indikasi -Berikan terapi TENS (stimulasi saraf transkutaneous), jika perlu Edukasi -Jelaskan tanda dan gejala infeksi -Anjurkan mengkonsumsi makanan tinggi kalori dan protein -Ajarkan prosedur perawatan luka secara mandiri Kolaborasi Kolaborasi prosedur debridement (mis. enzimatik, biologis, mekanis, autolitik), jika perlu - Kolaborasi pemberian antibiotik, jika perlu Perawatan Luka Bakar 1.14565 Definisi Mengidentifikasi dan merawat luka akut dan luka kronik akibat trauma termal.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (217, 'I.14566', 'Perawatan Luka Tekan', 'Mengidentifikasi dan merawat luka akibat penekanan pada tonjolan tulang.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (218, 'I.06203', 'Perawatan Mata', 'Mengidentifikasi dan merawat kesehatan mata serta mencegah terjadinya pembekakan pada mata.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (219, 'I.11356', 'Perawatan Mulut', 'Mengidentifikasi dan merawat kesehatan mulut serta mencegah terjadinya komplikasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (220, 'I.06204', 'P erawatan Neurovaskuler', 'Mengidentifikasi dan merawat pasien yang gangguan sensasi dan sirkulasi pada ekstremitas.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (221, 'I.14567', 'P erawatan Pasca Seksio Sesaria', 'Mengidentifikasi dan memberikan asuhan pada pasca persalinan seksio sesaria.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (222, 'I.06205', 'Perawatan Pascaanetesi', 'Mengidentifekasl dan merawat pasien setelah menjalani anestesi general atau regional.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (223, 'I.09304', 'Perawatan Pasien Ter minal', 'Mengidentifikasi dan merawat pasien yang dinyatakan tidak memilki harapan sembuh.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (224, 'I.10339', 'Pe rawatan Perkembangan', 'Mengidentifikasi dan merawat untuk memfasilitasi perkembangan yang optimal pada aspek motorik halus, motorik kasar, bahasa, kognitf, sosial, emosional di tiap tahapan usia anak.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (225, 'I.07227', 'Perawatan Persalinan', 'Mengedintifikasi dan mengelola proses persalinan serta mencegah terjadinya komplikasi Tindakan Observasi - Identifikasl kondisi proses persalinan - Monitor kondisi fisik dan psikologis pesien - Monitor kesejahteraan ibu (mis. tanda vital, kontraksi, lama, frekuensi, dan kekuatan) - Monitor kesejahteraan janin (Gerak janin 10x dalarn 12 jam) secaraberkelanjutan (DJJ dan volume air ketuban) - Monitor kemajuan persalinan - Monitor tanda-tanda persalinan (dorongan meneran. tekanan pada anus,perineum mononjol, vulva membuka) - Monitor kemajuan pembukaan menggunakan patograf saat fase aktif - Monitor tingkat nyeri selama parsalinan - Lakukan pemeriksaan Leopold Terapeutik - Berikan metode alternatif penghilang rasa sakit (mis pijat, aromaterapi. hípnosis) Edukasi - Jelaskan prosedur petolongan persalinan - Infomasikan kemaiuan persalinan - Anjurkan teknik relaksasi - Anjurkan tibuu mengosongkan kandung kemih - Anjurkan ibu cukup nutrisi - Ajarkan ibu cara mengenali tanda-tanda persalinan - Ajarkan ibu mengenali tanda bahaya persalinan Perawatan Persalinan Risiko Tinggi 1.07228 Definisi Memberikan asuhan persalinan pada janin multipel atau malposisi');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (226, 'I.07229', 'P erawatan Pra Seksio Sesar i a', 'Mengidentifikasi dan memberikan asuhan sebelum persalinan seksio sesaria.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (227, 'I.04165', 'Perawatan Retensi Urine', 'Mengidentifikasi dan meredakan distensi kandung kemih');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (228, 'I.14568', 'Perawatan Selang', 'Mengidentifikasi dan merawat pasien yang terpasang selang eksternal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (229, 'I.01022', 'Perawatan Selang Dada', 'Mengidentifikasi dan mengelola pasien yang terpasang selang dada');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (230, 'I.03133', 'Perawatan Selang Gastrointestinal', 'Mengidentifikasi dan merawat selang gastrointestinal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (231, 'I.14569', 'Ajarkan pasien dan keluarga cara merawat selang Perawatan Selang Umbilikal', 'Mengidentifikasi dan merawat akses infus umbilikal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (232, 'I.
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (233, 'I.14570', 'Perawatan Sirkumsisi', '- Mengidentifikasi dan merawat luka sirkumsisi serta mencegah komplikasi yang mungkin terjadi akibat sirkumsisi');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (234, 'I.14571', 'Perawatan Skin Graft', 'Mengidentifikasi dan merawat pasien dengan luka skin graft');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (235, 'I.06206', 'Perawatan Telinga', 'Mengidentifikasi, merawat dan mencegah gangguan telinga dan pendengaran.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (236, 'I.07230', 'Perawatan Terminasi Kehamilan', 'Mengidentifikasi dan memberikan asuhan terminasi kehamilan ( melakukan aborsi spontan atau elektif) sesuai dengan standar pelayanan yang sudah ditetapkan');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (237, 'I.14572', 'Perawatan Tirah Baring', 'Meningkatkan kenyamanan dan keamanan serta mencegah komplikasi pasien yang menjalani tirah baring.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (238, 'I.01023', 'Perawatan Trakheostomi', 'Mengidentifikasi dan merawat bersihan dan kapatenan jalan napas serta mencegah komplikasi akibat trakeostomi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (239, 'I.05182', 'Perawatan Traksi', 'Mengidentifikasi dan merawat pasien yang terpasang traksi untuk mengimobilisasi dan menstabilkan bagian tubuh.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (240, 'I.04167', 'Perawatan Urostomi', 'Mengidentifikasi dan merawat kesehatan pasien yang menjalani urostomi serta mencegah terjadinya komplikasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (241, 'I.12465', 'Perencanaan Pulang', 'Memfasilitasi perencanaan kebutuhan yang diperlukan pasien sejak masuk rumah sakit sampai setelah meninggalkan rumah sakit.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (242, 'I.14573', 'Persiapan Pembedahan', 'Mengidentifikasi dan menyiapkan pasien untuk menjalani prosedur operasi dan mencegah komplikasi serta perburukan saat prosedur operasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (243, 'I.14574', 'Persiapan Pemeriksaan Ultrasonografi (USG)', 'Mengidentifikasi dan menyiapkan pemeriksaan untuk menentukan perkembangan janin dan memberikan informasi yang akurat dan non-invasif, tanpa rasa sakit, dan aman. Tindakan Observasi - Identifikasi indikasi dilakukan pemeriksaan - Identifikasi pengetahuan tentang prosedur pemeriksaan - Monitor hasil pemeriksaan Terapeutik - Siapkan peralatan - Siapkan pasien secara fisik dan emosional - Diskusikan hasil pemeriksaan dengan tim medis - Jadwalkan pemeriksaan ulang atau prosedur tambahan, jika perlu Edukasi - Jelaskan tujuan dan prosedur pemeriksaan - Anjurkan puasa minimal 8 jam, jika perlu Pertolongan Pertama 1.02080 Definisi - - - Memberikan penanganan dasar dan segera pada kondisi kegawatdaruratan baik dengan alat maupun tanpa alat.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (244, 'I.03134', 'Pijat Laktasi', 'Meningkatkan produksi ASI dengan memicu homon oksitosin melalui pemijatan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (245, 'I.12466', 'Promosi Antisipasi Keluarga', 'Meningkatkan kesiapan keluarga untuk mencegah perkembangan atau krisis situasi akibat masalah kesehatan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (246, 'I.03135', 'Promosi ASI Eksklusif', 'Meningkatkan kemampuan ibu dalam memberikan ASI secara eksklusif (0-6 bulan). Tindakan Observasi - Identifikasi kebutuhan laktasi bagi ibu pada antenatal, intranatal dan postnatal Terapeutik - Fasilitasi ibu melakukan IMD (inisiasi menyusu dini) - Fasilitasi ibu untuk rawat gabung atau rooming in - - - Gunakan sendok dan cangkir jika bayi belum bisa menyusu - Dukung ibu menyusui dengan mendampingi ibu selama kegiatan menyusui berlangsung - Diskusikan dengan keluarga tentang ASI eksklusif - Siapkan kelas menyusui pada masa prenatai minimal 2 kali dan periode pascapartum minimal minimal 4 kali Edukasi - Jelaskan manfaat menyusui bagi ibu dan bayi - Jelaskan pentingnya menyusui di malam hari untuk mempertahankan dan meningkatkan produksi ASI - Jelaskan tanda-tanda bayi cukup ASI (mis. berat badan meningkat, BAK lebih dari 10 kali/hari, warna urine tidak pekat) - Jelaskan manfaat rawat gabung (rooming in) - Anjurkan ibu menyusui sesegera mungkin setelah melahirkan - Anjurkan ibu memberikan nutrisi kepada bayi hanya dengan ASI - Anjurkan ibu menyusui sesering mungkin setelah lahir sesuai kebutuhan bayi - Anjurkan ibu menjaga produksi ASI dengan memerah, walaupun kondisi ibu atau bayi terpisah Promosi Berat Badan 1.03136 Definisi Memfasilitasi peningkatan berat badan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (247, 'I.14577', 'Latihan mengekspresikan marah dengan tepat Promosi Teknik Kulit ke Kulit', 'Meningkatkan kontak kulit antara ibu dan bayi secara langsung agar bayi dapat menyusui Tindakan Observasi - monitor pernapasan bayi - Monitor tanda vital dan pendarahan setelah melahirkan Terapeutik - Berikan ibu kesempatan untuk rawat gabung atau rooming-in - Berikan posisi semi fowler setelah berada di ruangan rawat post partum - Buka pakaian bayi, pasang popok dan topi bayi - Letakkan bayi pada posisi tengkurap diantara payudara ibu - Berikan kehangatan dengan menyelimuti punggung bayi - Berikan kesempatan pada bayi untuk menyusu sampai selesai tanpa interupsi - Letakkan bayi di samping ibu atau letakkan tempat tidur bayi di samping tempat tidur ibu Terapeutik - Anjurkan ibu membuka pakaian bagian atas - Anjurkan ibu untuk membersihkan keringat di dada - Anjurkan memberikan kesempatan menyusui lebih dari 1 jam atau sampai bayi menunjukkan tanda-tanda siap menyusu ReduksiAnsietas I.09314 Definisi Meminimalkan kondisi individu dan pengalaman subjektif terhadap objek yang tidak jelas dan spesifik akibat antisipasi bahaya yang memungkinkan individu melakukan tindakan untuk menghadapi ancaman.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (248, 'I.14578', 'RegulasiTemperatur', 'Mempertahankan suhu tubuh dalam rentang normal');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (249, 'I.02081', 'Rehabilitasi jantung', 'Mengelola periode pemulihan fungsi jantung setelah mengalami gangguan yang berakibat pada ketidakseimbangan kebutuhan dan suplai oksigen miokard, serta meminimalkan kejadian serangan, perilaku beresiko dan dampak psikososial.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (250, 'I.14579', 'Rekonsiliasi Obat', 'Mengidentifikasi kesesuaian program pengibatan dengan obat yang diterima oleh pasien untuk mencegah terjadinya kesalahan pemberian obat');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (251, 'I.06027', 'Restrukturisasi Kognitif', 'Memfasilitasi mengubah pola pikir terdispersi, melihat diri sendiri dan dunia secara realistis');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (252, 'I.03139', 'Resusitasi Cairan', 'Memberikan cairan intravena dengan cepat sesuai indikasi');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (253, 'I.02082', 'Resusitasi Janin', 'Memberikan tindakan yang cepat dan tepat untuk mempertahankan perfusi plasenta ke janin.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (254, 'I.02083', 'Resusitasi Jantung Paru', 'Memberikan pertolongan pertama pada kondisi henti nafas dan digantung dengan teknik kompresi dada dan bantuan nafas');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (255, 'I.02084', 'Resusitasi Neonatus', 'Memberikan bantuan ventilasi dan sirkulasi yang adekuat untuk mempertahankan kehidupan bayi baru lahir');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (256, 'I.12473', 'Rujukan', 'Menyusun penanganan lebih lanjut dengan melakukan pelimpahan tugas dan tanggung jawab pemeriksaan dan perawatan pasien ke tenaga kesehatan atau kesehatan lain');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (257, 'I.03140', 'Rujukan Ke Kelas Laktasi Masa Kehamilan', 'Melakukan pelimpahan pelayanan kesehatan ibu hamil dalam persiapan menyusui ke kelas menyusui/klinik, laktasi/pojok laktasi, untuk mendapatkan konseling, informasi dan edukasi dari konselor menyusui minimal 1-2 kali kehamilan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (258, 'I.03141', 'Rujukan ke Kelas Laktasi Pascapersalinan', 'Melakukan pelimpahan layanan kesehatan ibu menyusui ke kelas menyusui/ klinik laktasi/pojok laktasi, untuk mendapatkan konseling, informasi dan edukasi dan konselor menyusui');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (259, 'I.03142', 'Rujukan ke Kelompok Dukungan Menyusui', 'Melakukan pelimpahan layanan kesehatan ibu hamil dan menyusui dalam mempersiapkan dan mempertahankan menyusui untuk mendapatkan konseling, informasi dan edukasi sehingga ibu mendapat dukungan menyusui selama di ruang perawatan atau komunitas.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (260, 'I.12474', 'Rujukan ke Layanan Masyarakat', 'Menyusun penatalaksanaan lebih lanjut layanan kesehatan dan keperawatan kepada sumber pelayanan kesehatan yang lebih lengkap bagi individu , keluarga dan kelompok di masyarakat.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (261, 'I.07231', 'Lakukan proses dokumentasi secara lengkap Rujukan ke Pelayanan Keluarga Berencana', 'Menyusun penata laksanaan lebih lanjut program perencanaan kehamilan anggota keluarga kepada institusi pelayanan keluarga berencana.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (262, 'I.10343', 'Skrining Bayi Sebelum Pemulangan', 'Mendeteksi secara dini suatu kelainan / penyakit yang belum jelas secara klinis dengan menggunakan sejumlah test, pemeriksaan atau prosedur');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (263, 'I.03143', 'Skrining gizi', 'Mendeteksi secara dini pasien yang beresiko mengalami malnutrisi dengan proses yang cepat untuk mencegah penurunan status gizi');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (264, 'I.14580', 'Skrining', 'Mendeteksi secara dini kemungkinan mengalami kanker agar dapat di lakukan penanganan sesegera mungkin');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (265, 'I.14581', 'Skrining kesehatan', 'Mendeteksi dini resiko masalah kesehatan dengan anamnesis, pemeriksaan fisik, dan prosedur lainya.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (266, 'I.14582', 'Skrining Penganiayaan/Persekusi', 'Mendeteksi secara dini penyebab penderitaan , rasa sakit, dan kematian secara sengaja');
