INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (269, 'I.01024', 'Skrining tuberkolosis', 'Mendeteksi dini risiko masalah kesehatan tuberculosis dengan anamnesis, pemeriksaan fisik, dan prosedur lainnya.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (270, 'I.01025', 'Stabilitas Jalan Napas', 'Mempertahankan kepatenan jalan napas baik tanpa alat maupun dengan alat bantu jalan napas.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (271, 'I.06208', 'Stimulasi Kognitif', 'Meningkatkan kesadaran dan pemahaman lingkungan dengan memanfaatkan perencanaan rangsangan.');
