INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (278, 'I.05184', 'Teknik latihan penguatan otot', 'memfasilitasi latihan otot resistif reguler untuk mempertahankan atau meningkatkan kekuatan otot.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (279, 'I.05185', 'Teknik latihan penguatan sendi', 'Menggunakan teknik gerakan tubuh aktif atau pasif untuk mempertahankan atau mengembalikan meningkatkan fleksibilitas sendi');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (280, 'I.08248', 'Teknik menenangkan', 'Teknik relaksasi dengan membentuknya imajinasi individu dengan menggunakan semua indera melalui pemprosesan kognitif untuk mengurangi stress.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (281, 'I.05186', 'Terapi aktivitas', 'Menggunakan aktivitas fisik, kognitif, social, dan spiritual tertentu untuk memulihkan keterlibatan frekuensi, atau durasi aktivitas individu atau kelompok.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (282, 'I.06209', 'Terapi akupresur', 'Menggunakan teknik penekanan pada titik tertentu untuk mengurangi nyeri, meningkatkan relaksasi, mencegah atau mengurangi mual.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (283, 'I.06210', 'Terapi akupuntur', 'Menggunakan metode penusukan jarum pada titik titik tertentu yang tepat di permukaan tubuh');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (284, 'I.09317', 'Terapi bantuan hewan', 'Menggunakan hewan untuk memberikan simulasi pemulihan kesehatan, pengalihan perhatiandan, relaksasi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (285, 'I.02085', 'Terapi bekam', 'Menggunakan metode penyedotan kulit dengan tekanan negative pada bagian bagian tertentu untuk mengeluarkan racun atau oksida dalam tubuh.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (286, 'I.10345', 'Terapi bercerita', 'Menggunakan cerita naratif seperti dongeng, mitos, legenda dengan improvisasi tertentu untuk memulihkan masalah fisik dan psikologis');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (287, 'I.10346', 'Terapi bermain', 'Menggunakan mainan atau media untuk memfasilitasi anak dalam mengkomunikasikan persepsi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (288, 'I.09318', 'Terapi biofeedback', 'Memfasilitasi kemampuan mengendalikan diri atas respons fisiologi dengan menggunakan monitor biofeedback.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (289, 'I.09320', 'Terapi Hipnisis', 'Memfasilitasi pencapaian konsentrasi penuh untuk menciptakan perubahan dalam sensasi,pikiran,atau perilaku.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (290, 'I.09321', 'Terapi Humor', 'Menggunakan humor untuk memudahkan membangun hubungan,mengurangi ketegangan dan kemarahan,atau mengatasi perasaan menyaksikan. Terapi Keluarga I.09322 Definisi Menggunakan anggota keluarga untuk menggerakan keluarga melakukan cara hidup yang lebih produktif.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (291, 'I.08249', 'Terapi Murattal', 'Menggunakan media al-qur’an (baik dengan mendengar atau membaca) untuk membantu meningkatkan pertumbuhan yang spesifik dalam tubuh baik secara fisiologis maupun psikologis.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (292, 'I.09323', ' Jelaskan tujuan dan manfaat terapi. Terapi Kognitif Perilaku', 'Menggunakan teknik berpikir,merasa dan berperilaku mengenai suatu kejadian untuk memulihkan penyadaran diri.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (293, 'I.02087', 'Kolaburasi dalam pemberian terapi (mis.psikofamaka,ECT) Terapi Lintah', 'Menggunakan lintah untuk menghilangkan kelebihan jaringan yang ditanam yang bercampur dengan darah vena.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (294, 'I.02086', 'Terapi Intravena', 'Memberikan dan memantau cairan dan/obat-obatan melalui intravena.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (295, 'I.13500', 'Jelaskan tujuan dan langkah-langkah prosedur. Terapi Kelompok', 'Menggunakan kelompok dengan masalah yang sama untuk memberikan dukungan emosional dan perilaku,melatih perilaku baru,dan berbagai informasi kesehatan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (296, 'I.08250', 'Terapi Musik', 'Menggunakan music untuk membantu mengubah perilaku,perasaan,atau fosiologi tubuh.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (297, 'I.03144', 'Terapi Menelan', 'Memulihkan kemampuan menelan untuk mencegah terjadinya komplikasi akibat gangguan menelan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (298, 'I.09324', 'Terapi Mileu', 'Menggunakan orang sumber daya,dan/atau kejadian di lingkungan sekitar untuk meningkatkan atau mengoptimalkan fungsi psikososial.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (299, 'I.09329', 'Terapi Seni', 'Menggunakan gambar atau bentuk kesenian lainnya untuk memfasilitasi komunikasi dan/atau penyembuhan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (300, 'I.09330', 'Terapi Sentuhan', 'Menggunakan tangan ke tubuh atau bagian tubuh tertentu untuk memfokuskan, mengarahkan, dan memodulasi medan energi dalam upaya penyembuhan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (301, 'I.09331', 'Terapi Trauma Anak', 'Memulihkan gangguan fisik dan psikologis yang terjadi akibat trauma pada anak');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (302, 'I.09332', 'Terapi Validasi', 'Menggunakan metode komunikasi terapeutik dengan berfokus pada konten emosional.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (303, 'I.02088', 'Torniket pneumatik', 'Memasang torniket untuk meminimalkan potensi cedera pasien');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (304, 'I.06211', 'Transcutaneous Electrical NerveStimulation (TENS)', 'Memberikan stimulasi pada kulit dan jaringan di bawahnya dengan arus listrik bertegangan rendah dan terkendali.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (305, 'I.14587', 'Transfer Pasien', 'Menyiapkan dan mengirimkan pasien ke ruangan lain (mis. Ruang rawat, ICU, ruang operasi, ruang pemeriksaan diagnostik) secara efektif dal aman');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (306, 'I.02089', 'Transfusi Darah', 'Menyiapkan dan memberikan produk darah atau plasma melalui set transfusi.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (307, 'I.14588', 'Triase', 'Memprioritaskan perawatan sesuai tingkat kegawatdaruratan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (308, 'I.14589', 'Triase Bencana', 'Menetapkan prioritas perawatan pasien pra dan pasca bencana untuk perawatan darurat sambil mengalokasikan sumber daya yang dibutuhkan.');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (309, 'I.14590', 'Triase Telepon', 'Menentukan sifat dan urgensi masalah dan memberikan arahan singkat tentang perawatan yang diperlukan melalui telepon');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (310, 'I.02090', 'Uji Laboratorium Di Tempat Tidur', 'Melakukan pemeriksaan laboratorium disamping tempat tidur pasien');
INSERT INTO siki (id, kode_intervensi, nama_intervensi, definisi) VALUES (311, 'I.08253', 'Yoga', 'Memberikan stimulasi peningkatan kesehatan, kenyamanan dan relaksasi melalui serangkaian teknik napas dan gerakan-gerakan tertentu');
